messages.content:
Tool response:
Tool: search_applicants_by_criteria
Description: Search Applicants By Criteria
Parameters:
    {
      "type": "object",
      "properties": {
        "camp_name": {
          "type": "string",
          "description": "The name of the camp (e.g., 'Robotics Camp').",
          "title": "Camp Name"
        },
        "term": {
          "type": "string",
          "description": "The term of the camp (e.g., 'Summer').",
          "title": "Term"
        },
        "year": {
          "type": "integer",
          "description": "The year of the camp (e.g., 2025).",
          "title": "Year"
        },
        "application_status": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter by application status (e.g., 'Incomplete'). If omitted, no status filter is applied.",
          "title": "Application Status"
        },
        "missing_document_type": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter for applicants who do NOT have this specific document type uploaded (e.g., 'Recommendation Letter'). If omitted, no missing document filter is applied.",
          "title": "Missing Document Type"
        }
      },
      "required": [
        "camp_name",
        "term",
        "year"
      ]
    }
